        '2026-08-13T17:00:00.000Z',
    ],
    ['1320', '3x 87-90 Upgrade', '2026-08-13T17:00:00.000Z'],
    ['1316', '1 of 3 FUTTIES Team 2 Player Pick', '2026-08-12T17:00:00.000Z'],
    ['1319', 'Eusébio', '2026-08-23T17:00:00.000Z'],
    [
        '1298',
        '1 of 3 94+ GOTG or FUTTIES Icon or Hero Player Pick',
        '2026-08-16T17:00:00.000Z',
    ],
    ['1302', 'Fernando Torres', '2026-08-21T17:00:00.000Z'],
    ['1306', 'Frenkie de Jong', '2026-08-21T17:00:00.000Z'],
    ['1310', '10x 84+ Upgrade', '2026-08-14T17:00:00.000Z'],
    ['1274', 'Antonio Di Natale', '2026-08-14T17:00:00.000Z'],
    ['1261', '5x 80+ Upgrade', '2026-08-21T17:00:00.000Z'],
    ['1248', 'Johan Cruyff', '2026-08-13T17:00:00.000Z'],
    ['1237', '89 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1236', '88 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1231', '83 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1235', '87 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1238', '90 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1234', '86 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1232', '84 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1233', '85 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['1239', '91 OVR Token Swap', '2026-08-13T17:00:00.000Z'],
    ['7', 'Gold Upgrade', '2035-07-30T17:00:00.000Z'],
].map(([sourceId, sourceName, expiresAt]) => ({
    sourceId,
    sourceName,
    expiresAt,
}));

const triggerInput = $input.first().json;
const workflowState = $getWorkflowStaticData('global').sbcCatalogV1 ?? {};
let configValid = true;
let failureReason = null;
let triggerSource = null;
let mode = 'dry_run';

if (
    triggerInput?.triggerSource === 'manual' &&
    triggerInput?.requestedMode === 'dry_run'
) {
    triggerSource = 'manual';
} else if (
    triggerInput?.triggerSource === 'schedule' &&
    triggerInput?.requestedMode === 'apply'
) {
    triggerSource = 'schedule';
    mode = 'apply';
    if (
        !Array.isArray(workflowState.lastSuccessfulItems) ||
        workflowState.lastSuccessfulItems.length === 0
    ) {
        configValid = false;
        failureReason =
            'Scheduled apply is blocked until a production webhook bootstrap completes with fresh HTTP 201';
    }
} else if (
    triggerInput?.body &&
    typeof triggerInput.body === 'object' &&
    !Array.isArray(triggerInput.body) &&
    Object.keys(triggerInput.body).length === 1 &&
    ['dry_run', 'apply'].includes(triggerInput.body.mode)
) {
    triggerSource = 'webhook';
    mode = triggerInput.body.mode;
} else {
    configValid = false;
    failureReason =
        'Trigger contract is invalid; use manual dry-run, scheduled apply, or exact webhook body {"mode":"dry_run|apply"}';
}

return [
    {
        json: {
            settings: {
                mode,
                pricingEndpoint:
                    'https://store.arab-ut.com/api/automation/v1/pricing/coins/sbc-bases',
                pricingPath: '/api/automation/v1/pricing/coins/sbc-bases',
                sourceEndpoint:
                    'https://api-fc26.easysbc.io/sbc-sets?page=1&limit=200',
                catalogEndpoint:
                    'https://store.arab-ut.com/api/automation/v1/catalog/sbc/snapshots',
                catalogSource: 'n8n-sbc',
                sourceMinCount: 20,
                sourceLimit: 200,
                minimumExpiryLeadSeconds: 7200,
                approvedBaseline: {
                    sourceCount: 56,
                    eligibleCount: 39,
                    observedAt: '2026-08-12T05:46:36.701Z',
                    approvedAt: '2026-08-12T05:46:36.701Z',
                    approvedBy: 'operator',
                    eligibleItems: approvedEligibleItems,
                },
            },
            eventId: ulid(),
            runId: ulid(),
            generatedAt: generatedAt(),
            configValid,
            failureReason,
            triggerSource,
        },
    },
];

/* eslint-disable */
const item = $input.first().json;
const secret = $env.N8N_SBC_PRICING_READ_SECRET;

if (!secret) {
    return [
        {
            json: {
                ...item,
                pricingReadSigned: false,
                failureReason:
                    'N8N_SBC_PRICING_READ_SECRET is not configured on the n8n host',
            },
        },
    ];
}

const crypto = require('crypto');
const timestamp = String(Math.floor(Date.now() / 1000));
const canonical = `${timestamp}\nGET\n${item.settings.pricingPath}\n`;
const signature = crypto
    .createHmac('sha256', secret)
    .update(canonical)
    .digest('hex');

return [{ json: { ...item, pricingReadSigned: true, timestamp, signature } }];

/* eslint-disable */
const response = $input.first().json;
const statusCode = Number(response.statusCode || 200);
let body = response.body ?? response;

if (typeof body === 'string') {
    try {
        body = JSON.parse(body);
    } catch {}
}

function failure(reason) {
    return [{ json: { valid: false, failureReason: reason } }];
}

if (
    response.error ||
    response.errorMessage ||
    statusCode !== 200 ||
    !body ||
    typeof body !== 'object' ||
    Array.isArray(body)
) {
    return failure(`Laravel SBC pricing read failed with HTTP ${statusCode}`);
}

if (
    JSON.stringify(Object.keys(body)) !==
    JSON.stringify(['schemaVersion', 'pricingVersion', 'pricedAt', 'quotes'])
) {
    return failure('SBC pricing response has an unexpected top-level shape');
}

if (
    body.schemaVersion !== 1 ||
    !Number.isInteger(body.pricingVersion) ||
    body.pricingVersion < 1 ||
    typeof body.pricedAt !== 'string'
) {
    return failure('SBC pricing response metadata is invalid');
}

if (
    !body.quotes ||
    JSON.stringify(Object.keys(body.quotes)) !==
        JSON.stringify(['playstation_fast', 'pc'])
) {
    return failure(
        'SBC pricing response must contain exactly the PlayStation fast and PC quotes',
    );
}

const expected = {
    playstation_fast: { platform: 'playstation', delivery: 'fast' },
    pc: { platform: 'pc', delivery: null },
};

for (const [key, identity] of Object.entries(expected)) {
    const quote = body.quotes[key];
    if (
        !quote ||
        JSON.stringify(Object.keys(quote)) !==
            JSON.stringify(['platform', 'delivery', 'quantity', 'totalHalalah'])
    ) {
        return failure(`${key} quote has an unexpected shape`);
    }
    if (
        quote.platform !== identity.platform ||
        quote.delivery !== identity.delivery ||
        quote.quantity !== 1_000_000
    ) {
        return failure(`${key} is not the authoritative one-million quote`);
    }
    if (!Number.isInteger(quote.totalHalalah) || quote.totalHalalah <= 0) {
        return failure(`${key} totalHalalah is invalid`);
    }
}

return [{ json: { valid: true, failureReason: null, pricing: body } }];

/* eslint-disable */
const config = $('Config').first().json;

function result(fields) {
    return [{ json: { ...config, ...fields } }];
}

function fail(reason, records = []) {
    return result({
        translationPlanValid: false,
        translationReady: false,
        failureReason: reason,
        sourceRecords: records,
        missingTranslations: [],
        prompt: null,
    });
}

let records = $input.all().map((item) => item.json);
if (records.length === 1 && Array.isArray(records[0]?.body))
    records = records[0].body;
if (records.length === 1 && Array.isArray(records[0]?.data))
    records = records[0].data;

const settings = config.settings;
if (records.length < settings.sourceMinCount) {
    return fail(
        `EasySBC source is below the minimum complete record count of ${settings.sourceMinCount}`,
        records,
    );
}
if (records.length >= settings.sourceLimit) {
    return fail(
        `EasySBC pagination is ambiguous at the configured limit of ${settings.sourceLimit}`,
        records,
    );
}

const allowedCategories = new Set([1, 2, 3, 4, 5, 6]);
const allowedModes = new Set(['NON_REPEATABLE', 'UNLIMITED', 'REFRESH']);
const ids = new Set();
for (let index = 0; index < records.length; index += 1) {
    const record = records[index];
    const label = `EasySBC record ${index}`;
    if (!record || typeof record !== 'object' || Array.isArray(record))
        return fail(`${label} is not an object`, records);
    if (!Number.isInteger(record.id) || record.id <= 0)
        return fail(`${label} id is invalid`, records);
    if (ids.has(record.id))
        return fail(
            `EasySBC source contains duplicate id ${record.id}`,
            records,
        );
    ids.add(record.id);
    if (
        typeof record.name !== 'string' ||
        !record.name.trim() ||
        record.name.length > 220
    )
        return fail(`${label} name is invalid`, records);
    if (!allowedCategories.has(record.categoryId))
        return fail(`${label} categoryId is invalid`, records);
    if (!Number.isInteger(record.sbcsCount) || record.sbcsCount <= 0)
        return fail(`${label} sbcsCount is invalid`, records);
    if (typeof record.repeatable !== 'boolean')
        return fail(`${label} repeatable is invalid`, records);
    if (!allowedModes.has(record.repeatabilityMode))
        return fail(`${label} repeatabilityMode is invalid`, records);
    if (!Number.isInteger(record.endTime) || record.endTime <= 0)
        return fail(`${label} endTime is invalid`, records);
    if (typeof record.active !== 'boolean')
        return fail(`${label} active is invalid`, records);
    if (!Number.isFinite(Number(record.psPrice)) || Number(record.psPrice) <= 0)
        return fail(`${label} psPrice is invalid`, records);
    if (!Number.isFinite(Number(record.pcPrice)) || Number(record.pcPrice) <= 0)
        return fail(`${label} pcPrice is invalid`, records);
}

const now = Math.floor(new Date(config.generatedAt).getTime() / 1000);
const eligible = records.filter((record) => {
    if (!record.active) return false;
    if (record.endTime <= now + settings.minimumExpiryLeadSeconds) return false;
    if (/\b(?:bronze|silver)\b/i.test(record.name)) return false;
    if (Number(record.psPrice) < 1500) return false;
    if (!record.repeatable && Number(record.psPrice) < 20_000) return false;
    return Number(record.pcPrice) > 0;
});
if (eligible.length === 0)
    return fail('EasySBC source produced no eligible challenges', records);

const globalData = $getWorkflowStaticData('global');
const cache = globalData.sbcCatalogV1?.translations ?? {};
const missingTranslations = [];

for (const record of eligible) {
    const sourceName = record.name.trim();
    const key = `${record.id}\u0000${sourceName}`;
    const cached = cache[key];
    if (!cached) {
        missingTranslations.push({ id: String(record.id), sourceName });
        continue;
    }
    if (cached.sourceName !== sourceName) {
        return fail(
            `Cached translation source name mismatch for EasySBC id ${record.id}`,
            records,
        );
    }
    if (
        typeof cached.nameAr !== 'string' ||
        cached.nameAr.length < 2 ||
        cached.nameAr.length > 120 ||
        !/[\u0600-\u06ff]/.test(cached.nameAr) ||
        /[A-Za-z]/.test(cached.nameAr)
    ) {
        return fail(
            `Cached translation for EasySBC id ${record.id} must be Arabic-only and at most 120 characters`,
            records,
        );
    }
}

const prompt = missingTranslations.length
    ? [
          'Translate these exact EA FC Squad Building Challenge names into concise natural Gulf gaming Arabic.',
          'Preserve meaning and transliterate player names. Translate pack, pick, upgrade, token, icon, hero, and evolution terms.',
          'Arabic script and digits only: no Latin letters, no generic prefix, no commentary.',
          'Keep every id and sourceName byte-for-byte exact. Do not add, remove, or reorder entries.',
          'Return only a JSON array with exactly these keys: id, sourceName, nameAr.',
          `INPUT:${JSON.stringify(missingTranslations)}`,
      ].join('\n')
    : null;

return result({
    translationPlanValid: true,
    translationReady: missingTranslations.length === 0,
    failureReason: null,
    sourceRecords: records,
    missingTranslations,
    prompt,
});

/* eslint-disable */
const plan = $('Prepare Translations').first().json;

function result(fields) {
    return [{ json: { ...plan, ...fields } }];
}

function fail(reason) {
    return result({
        translationReady: false,
        failureReason: reason,
    });
}

function normalizeApprovedFcTerms(value) {
    return value
        .trim()
        .replace(/\bFUTTIES\b/gi, '\u0641\u0648\u062a\u064a\u0632')
        .replace(
            /\bFOF\b/gi,
            '\u0645\u0647\u0631\u062c\u0627\u0646 \u0643\u0631\u0629 \u0627\u0644\u0642\u062f\u0645',
        )
        .replace(
            /\bGOTG\b/gi,
            '\u0639\u0638\u0645\u0627\u0621 \u0627\u0644\u0644\u0639\u0628\u0629',
        )
        .replace(
            /\bTOTW\b/gi,
            '\u0641\u0631\u064a\u0642 \u0627\u0644\u0623\u0633\u0628\u0648\u0639',
        )
        .replace(/\bOVR\b/gi, '\u062a\u0642\u064a\u064a\u0645')
        .replace(/\bEVO\b/gi, '')
        .replace(
            /\bSBCs?\b/gi,
            '\u062a\u062d\u062f\u064a\u0627\u062a \u0628\u0646\u0627\u0621 \u0627\u0644\u062a\u0634\u0643\u064a\u0644\u0627\u062a',
        )
        .replace(/(\d+)\s*x\b/gi, '$1\u00d7')
        .replace(/\s{2,}/g, ' ')
        .trim();
}

if (!plan.translationPlanValid || !Array.isArray(plan.missingTranslations)) {
    return fail(plan.failureReason || 'Translation plan is invalid');
}
if (plan.missingTranslations.length === 0) {
    return result({ translationReady: true, failureReason: null });
}

const response = $input.first().json;
let raw = response.text ?? response.output ?? response.response ?? response;
if (typeof raw === 'object' && raw !== null) raw = JSON.stringify(raw);
if (typeof raw !== 'string')
    return fail('Gemini translation response is missing');
raw = raw
    .trim()
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/, '');

let translated;
try {
    translated = JSON.parse(raw);
} catch {
    return fail('Gemini translation response is not valid JSON');
}
if (!Array.isArray(translated))
    return fail('Gemini translation response must be a JSON array');
if (translated.length !== plan.missingTranslations.length) {
    return fail(
        `Gemini translation count ${translated.length} does not match requested count ${plan.missingTranslations.length}`,
    );
}

const expected = new Map(
    plan.missingTranslations.map((pair) => [String(pair.id), pair.sourceName]),
);
const staged = {};
const seen = new Set();
for (const entry of translated) {
    if (!entry || typeof entry !== 'object' || Array.isArray(entry))
        return fail('Gemini translation entry is invalid');
    if (!Object.hasOwn(entry, 'id') || !Object.hasOwn(entry, 'sourceName'))
        return fail(
            'Gemini translation entry is missing exact identity fields',
        );
    const id = String(entry.id);
    if (!expected.has(id))
        return fail(`Gemini returned unexpected EasySBC id ${id}`);
    if (seen.has(id)) return fail(`Gemini returned duplicate EasySBC id ${id}`);
    seen.add(id);
    if (entry.sourceName !== expected.get(id))
        return fail(`Gemini source name mismatch for EasySBC id ${id}`);
    const nameAr =
        typeof entry.nameAr === 'string'
            ? normalizeApprovedFcTerms(entry.nameAr)
            : '';
    if (
        nameAr.length < 2 ||
        nameAr.length > 120 ||
        !/[\u0600-\u06ff]/.test(nameAr) ||
        /[A-Za-z]/.test(nameAr)
    ) {
        return fail(
            `Gemini translation for EasySBC id ${id} must be Arabic-only and at most 120 characters`,
        );
    }
    const sourceName = expected.get(id);
    staged[`${id}\u0000${sourceName}`] = {
        sourceName,
        nameAr,
    };
}
if (seen.size !== expected.size)
    return fail('Gemini translation response is incomplete');

const globalData = $getWorkflowStaticData('global');
const state = globalData.sbcCatalogV1 ?? {};
globalData.sbcCatalogV1 = {
    ...state,
    translations: { ...(state.translations ?? {}), ...staged },
};

return result({
    translationReady: true,
    failureReason: null,
    missingTranslations: [],
});

/* eslint-disable */
const config = $('Config').first().json;
const pricingState = $('Evaluate Pricing Read').first().json;

function fail(reason) {
    return [{ json: { ...config, valid: false, failureReason: reason } }];
}

function isApprovedEasySbcImage(url) {
    const prefix = 'https://assets.easysbc.io/';

    return (
        typeof url === 'string' &&
        url.length > prefix.length &&
        url.length <= 2048 &&
        url.startsWith(prefix) &&
        !/[\s\\]/.test(url)
    );
}

function catalogImage(record) {
    const playerReward = Array.isArray(record.rewards)
        ? record.rewards.find(
              (reward) =>
                  reward &&
                  typeof reward === 'object' &&
                  !Array.isArray(reward) &&
                  reward.type === 'player' &&
                  typeof reward.rewardImgURL === 'string' &&
                  reward.rewardImgURL.length > 0,
          )
        : null;

    return playerReward?.rewardImgURL ?? record.imageURL ?? null;
}

if (!pricingState.valid || !pricingState.pricing) {
    return fail(
        pricingState.failureReason ||
            'Authoritative SBC pricing bases are unavailable',
    );
}

let records = $input.all().map((item) => item.json);
if (records.length === 1 && Array.isArray(records[0]?.sourceRecords))
    records = records[0].sourceRecords;
if (records.length === 1 && Array.isArray(records[0]?.body))
    records = records[0].body;
if (records.length === 1 && Array.isArray(records[0]?.data))
    records = records[0].data;

const settings = config.settings;
if (records.length < settings.sourceMinCount) {
    return fail(
        `EasySBC source is below the minimum complete record count of ${settings.sourceMinCount}`,
    );
}
if (records.length >= settings.sourceLimit) {
    return fail(
        `EasySBC pagination is ambiguous at the configured limit of ${settings.sourceLimit}`,
    );
}

const allowedCategories = new Set([1, 2, 3, 4, 5, 6]);
const allowedModes = new Set(['NON_REPEATABLE', 'UNLIMITED', 'REFRESH']);
const ids = new Set();

for (let index = 0; index < records.length; index += 1) {
    const record = records[index];
    const label = `EasySBC record ${index}`;
    if (!record || typeof record !== 'object' || Array.isArray(record))
        return fail(`${label} is not an object`);
    if (!Number.isInteger(record.id) || record.id <= 0)
        return fail(`${label} id is invalid`);
    if (ids.has(record.id))
        return fail(`EasySBC source contains duplicate id ${record.id}`);
    ids.add(record.id);
    if (
        typeof record.name !== 'string' ||
        !record.name.trim() ||
        record.name.length > 220
    )
        return fail(`${label} name is invalid`);
    if (!allowedCategories.has(record.categoryId))
        return fail(`${label} categoryId is invalid`);
    if (
        record.description != null &&
        (typeof record.description !== 'string' ||
            record.description.length > 4800)
    )
        return fail(`${label} description is invalid`);
    if (!Number.isInteger(record.sbcsCount) || record.sbcsCount <= 0)
        return fail(`${label} sbcsCount is invalid`);
    if (typeof record.repeatable !== 'boolean')
        return fail(`${label} repeatable is invalid`);
    if (!allowedModes.has(record.repeatabilityMode))
        return fail(`${label} repeatabilityMode is invalid`);
    if (!Number.isInteger(record.endTime) || record.endTime <= 0)
        return fail(`${label} endTime is invalid`);
    if (typeof record.active !== 'boolean')
        return fail(`${label} active is invalid`);
    if (!Number.isFinite(Number(record.psPrice)) || Number(record.psPrice) <= 0)
        return fail(`${label} psPrice is invalid`);
    if (!Number.isFinite(Number(record.pcPrice)) || Number(record.pcPrice) <= 0)
        return fail(`${label} pcPrice is invalid`);
    if (
        record.repeats != null &&
        (!Number.isInteger(record.repeats) || record.repeats <= 0)
    )
        return fail(`${label} repeats is invalid`);
    if (record.imageURL != null) {
        if (!isApprovedEasySbcImage(record.imageURL))
            return fail(`${label} imageURL is not an approved EasySBC asset`);
    }
    if (record.rewards != null && !Array.isArray(record.rewards))
        return fail(`${label} rewards is invalid`);
    for (const reward of record.rewards ?? []) {
        if (
            reward &&
            typeof reward === 'object' &&
            !Array.isArray(reward) &&
            reward.type === 'player' &&
            reward.rewardImgURL != null &&
            !isApprovedEasySbcImage(reward.rewardImgURL)
        ) {
            return fail(
                `${label} player rewardImgURL is not an approved EasySBC asset`,
            );
        }
    }
}

const now = Math.floor(new Date(config.generatedAt).getTime() / 1000);
const expiryCutoff = now + settings.minimumExpiryLeadSeconds;
function ineligibilityReason(record) {
    if (!record.active) return 'inactive';
    if (record.endTime <= expiryCutoff) return 'inside_expiry_lead';
    if (/\b(?:bronze|silver)\b/i.test(record.name)) return 'excluded_name';
    if (Number(record.psPrice) < 1500) return 'ps_below_minimum';
    if (!record.repeatable && Number(record.psPrice) < 20_000)
        return 'nonrepeatable_ps_below_minimum';
    if (Number(record.pcPrice) <= 0) return 'pc_not_positive';
    return null;
}

const eligible = records.filter((record) => !ineligibilityReason(record));

if (eligible.length === 0)
    return fail('EasySBC source produced no eligible challenges');

const baseline = settings.approvedBaseline;
if (
    !baseline ||
    !Number.isInteger(baseline.sourceCount) ||
    baseline.sourceCount <= 0 ||
    !Number.isInteger(baseline.eligibleCount) ||
    baseline.eligibleCount <= 0 ||
    baseline.approvedBy !== 'operator' ||
    typeof baseline.observedAt !== 'string' ||
    !baseline.observedAt ||
    typeof baseline.approvedAt !== 'string' ||
    !baseline.approvedAt ||
    !Array.isArray(baseline.eligibleItems) ||
    baseline.eligibleItems.length !== baseline.eligibleCount
) {
    return fail(
        'A manually approved operator bootstrap baseline is required before SBC catalog apply',
    );
}

const globalData = $getWorkflowStaticData('global');
const workflowState = globalData.sbcCatalogV1 ?? {};
const lastCounts = workflowState.lastSuccessfulCounts;
const previousItems = Array.isArray(workflowState.lastSuccessfulItems)
    ? workflowState.lastSuccessfulItems
    : baseline.eligibleItems;
const sourceSafetyFloor = Math.max(
    settings.sourceMinCount,
    lastCounts?.sourceCount
        ? Math.floor(Number(lastCounts.sourceCount) * 0.85)
        : Math.floor(baseline.sourceCount * 0.85),
);
if (records.length < sourceSafetyFloor) {
    return fail(
        `EasySBC source count ${records.length} is below source safety floor of ${sourceSafetyFloor}`,
    );
}

const sourceById = new Map(
    records.map((record) => [String(record.id), record]),
);
const eligibleById = new Map(
    eligible.map((record) => [String(record.id), record]),
);
const previousIds = new Set();
const expectedDepartures = [];
const unexpectedMissing = [];
for (const previous of previousItems) {
    if (
        !previous ||
        typeof previous.sourceId !== 'string' ||
        !previous.sourceId ||
        typeof previous.sourceName !== 'string' ||
        !previous.sourceName ||
        typeof previous.expiresAt !== 'string' ||
        !previous.expiresAt ||
        previousIds.has(previous.sourceId)
    ) {
        return fail('SBC safety baseline contains an invalid prior item');
    }
    previousIds.add(previous.sourceId);
    const eligibleRecord = eligibleById.get(previous.sourceId);
    if (eligibleRecord) {
        if (eligibleRecord.name.trim() !== previous.sourceName) {
            return fail(
                `EasySBC source name changed for prior id ${previous.sourceId}`,
            );
        }
        continue;
    }

    const sourceRecord = sourceById.get(previous.sourceId);
    if (sourceRecord) {
        const reason = ineligibilityReason(sourceRecord);
        if (!reason) {
            unexpectedMissing.push(previous.sourceId);
        } else {
            expectedDepartures.push({ sourceId: previous.sourceId, reason });
        }
        continue;
    }

    const previousExpiry = Date.parse(previous.expiresAt);
    if (
        Number.isFinite(previousExpiry) &&
        previousExpiry <= expiryCutoff * 1000
    ) {
        expectedDepartures.push({
            sourceId: previous.sourceId,
            reason: 'expired_or_inside_expiry_lead',
        });
    } else {
        unexpectedMissing.push(previous.sourceId);
    }
}
if (unexpectedMissing.length) {
    return fail(
        `EasySBC has unexpected missing prior IDs: ${unexpectedMissing.join(', ')}`,
    );
}

const priorEligibleAfterExpectedDepartures = Math.max(
    0,
    previousItems.length - expectedDepartures.length,
);
const eligibleSafetyFloor = Math.max(
    1,
    Math.floor(priorEligibleAfterExpectedDepartures * 0.8),
);
if (eligible.length < eligibleSafetyFloor) {
    return fail(
        `EasySBC eligible count ${eligible.length} is below identity-adjusted safety floor of ${eligibleSafetyFloor}`,
    );
}
const newSourceIds = eligible
    .map((record) => String(record.id))
    .filter((sourceId) => !previousIds.has(sourceId));

const translationCache = workflowState.translations ?? {};
function approvedArabicName(record) {
    const sourceName = record.name.trim();
    const cached = translationCache[`${record.id}\u0000${sourceName}`];
    if (!cached)
        throw new Error(
            `Approved Arabic translation is missing for EasySBC id ${record.id}`,
        );
    if (cached.sourceName !== sourceName)
        throw new Error(
            `Approved Arabic translation source name mismatch for EasySBC id ${record.id}`,
        );
    if (
        typeof cached.nameAr !== 'string' ||
        cached.nameAr.length < 2 ||
        cached.nameAr.length > 120 ||
        !/[\u0600-\u06ff]/.test(cached.nameAr) ||
        /[A-Za-z]/.test(cached.nameAr)
    ) {
        throw new Error(
            `Approved translation for EasySBC id ${record.id} must be Arabic-only and at most 120 characters`,
        );
    }
    return cached.nameAr.trim();
}

for (const record of eligible) {
    try {
        approvedArabicName(record);
    } catch (error) {
        return fail(error.message);
    }
}

